import type { DaySpend, Provider, ProviderSpend, UsageWindow } from "./types.ts";

const MINUTE_MS = 60_000;
const HOUR_MS = 60 * MINUTE_MS;
const DAY_MS = 24 * HOUR_MS;

export function clampUsedPercent(usedPercent: number): number {
	if (!Number.isFinite(usedPercent)) return 0;
	return Math.max(0, Math.min(100, Math.round(usedPercent)));
}

/** Cents -> `$3.80`. Prepaid spend is a dollar figure, never a percentage. */
export function formatUsd(cents: number): string {
	if (!Number.isFinite(cents)) return "$0.00";
	return `$${(cents / 100).toFixed(2)}`;
}

export function resetAtMs(resetAt?: number): number | null {
	if (resetAt == null || !Number.isFinite(resetAt)) return null;
	return resetAt > 1e12 ? resetAt : resetAt * 1000;
}

/** Compact remaining duration: "47m", "3h 54m", "6d 7h". */
export function formatResetDuration(ms: number): string {
	if (ms <= 0) return "now";
	const totalMins = Math.floor(ms / 60_000);
	if (totalMins < 60) return `${totalMins}m`;
	const hours = Math.floor(totalMins / 60);
	const mins = totalMins % 60;
	if (hours >= 24) {
		const days = Math.floor(hours / 24);
		const remHours = hours % 24;
		return remHours > 0 ? `${days}d ${remHours}h` : `${days}d`;
	}
	return mins > 0 ? `${hours}h ${mins}m` : `${hours}h`;
}

const SESSION_NAMES = new Set(["session", "5h", "rolling"]);

export function windowLetter(name: string): string {
	if (SESSION_NAMES.has(name)) return "s";
	if (name === "weekly") return "w";
	if (name === "monthly") return "m";
	const initial = name.trim().charAt(0).toLowerCase();
	return initial || "?";
}

function windowRank(name: string): number {
	if (name === "monthly") return 2;
	if (name === "weekly") return 1;
	return 0;
}

/** Status-bar windows preserve every provider-reported policy window. */
export function statusBarWindows(windows: readonly UsageWindow[]): UsageWindow[] {
	return [...windows];
}

/** Highest use wins; ties prefer the longer window (weekly over empty session). */
export function bottleneckWindow(windows: readonly UsageWindow[]): UsageWindow | null {
	const candidates = statusBarWindows(windows);
	let best: UsageWindow | null = null;
	let bestPercent = -1;
	let bestRank = -1;
	for (const window of candidates) {
		const usedPercent = clampUsedPercent(window.usedPercent);
		const rank = windowRank(window.name);
		if (usedPercent > bestPercent || (usedPercent === bestPercent && rank > bestRank)) {
			best = window;
			bestPercent = usedPercent;
			bestRank = rank;
		}
	}
	return best;
}

export function formatFooterChip(window: UsageWindow, now: number): string {
	const usedPercent = clampUsedPercent(window.usedPercent);
	const letter = windowLetter(window.name);
	const resetMs = resetAtMs(window.resetAt);
	const duration = resetMs == null ? "" : formatResetDuration(resetMs - now);
	const remaining = duration && duration !== "now" ? duration : "";
	if (usedPercent >= 100) {
		return remaining ? `${letter} ${remaining}` : letter;
	}
	return remaining ? `${letter} ${usedPercent}% ${remaining}` : `${letter} ${usedPercent}%`;
}

export type FooterSummary = {
	id: string;
	name: string;
	label: string;
	usedPercent: number;
	resetMs: number | null;
};

/** Local midnight that opens the next calendar month: where a prepaid month ends. */
export function monthEndAt(now: number): number {
	const at = new Date(now);
	return new Date(at.getFullYear(), at.getMonth() + 1, 1).getTime();
}

/** This month's reading of a prepaid balance, in one place: the card row, the chart and the footer chip. */
export type PrepaidMonth = {
	/** Dollars spent since the first of this month, in cents. */
	spentCents: number;
	/** Share of the month's credit spent, 0–100. */
	usedPercent: number;
	/** Local midnight that ends the month, in ms. */
	resetMs: number;
};

/**
 * How much of this month's credit a prepaid balance has spent. What the month
 * started with is this month's spend plus what is left, so a top-up raises the
 * denominator instead of hiding the spend. No spend and nothing left reads as
 * 0: the month has taken nothing yet.
 */
export function prepaidMonth(
	days: readonly DaySpend[],
	balanceCents: number | null | undefined,
	now: number,
): PrepaidMonth {
	const at = new Date(now);
	const firstDay = `${at.getFullYear()}-${String(at.getMonth() + 1).padStart(2, "0")}-01`;
	const spent = days.reduce((sum, day) => (day.day >= firstDay ? sum + Math.max(0, day.cents) : sum), 0);
	const credit = spent + Math.max(0, balanceCents ?? 0);
