/** When a ticket stops being spendable, or null for one without an expiry (i64::MAX) or one already gone. */
export function ticketExpiresMs(expiresAt: number, now = Date.now()): number | null {
	const ms = resetAtMs(expiresAt);
	if (ms == null || ms <= now || ms - now > 366 * DAY_MS) return null;
	return ms;
}

edits.newText:
/** When a ticket stops being spendable, or null for one without an expiry (i64::MAX) or one already gone. */
export function ticketExpiresMs(expiresAt: number, now = Date.now()): number | null {
	const ms = resetAtMs(expiresAt);
	if (ms == null || ms <= now || ms - now > 366 * DAY_MS) return null;
	return ms;
}

/** A ticket that clears a single model's allowance, or the whole weekly limit. */
type TicketScope = { scope?: string; model?: string };

/** `Fable reset` for a model ticket, `Full reset` for one that clears weekly usage. */
export function ticketName(ticket: TicketScope): string {
	if (ticket.scope === "model" && ticket.model) return `${ticket.model} reset`;
	return "Full reset";
}

/** What spending the ticket buys, in the card's own words. */
export function ticketEffect(ticket: TicketScope): string {
	if (ticket.scope === "model" && ticket.model) {
		return `Restores the ${ticket.model} allowance; the weekly limit is untouched.`;
	}
	return "Resets weekly usage now.";
}

/** Tickets still spendable at `now`, soonest to lapse first. */
export function liveTickets<T extends { expiresAt: number }>(tickets: readonly T[], now = Date.now()): T[] {
	const live: { ticket: T; at: number }[] = [];
	for (const ticket of tickets) {
		const at = resetAtMs(ticket.expiresAt);
		if (at == null || at <= now) continue;
		live.push({ ticket, at });
	}
	return live.sort((a, b) => a.at - b.at).map((entry) => entry.ticket);
}

/** The soonest full ticket: only one that clears weekly usage drives the weekly chart. */
export function weeklyTicket<T extends { expiresAt: number } & TicketScope>(
	tickets: readonly T[],
	now = Date.now(),
): T | undefined {
	return liveTickets(
		tickets.filter((ticket) => ticket.scope !== "model"),
		now,
	)[0];
}

