/** Status-bar windows preserve every provider-reported policy window. */
export function statusBarWindows(windows: readonly UsageWindow[]): UsageWindow[] {
	return [...windows];
}

/** Highest use wins; ties prefer the longer window (weekly over empty session). */
export function bottleneckWindow(windows: readonly UsageWindow[]): UsageWindow | null {
	const candidates = statusBarWindows(windows);
	let best: UsageWindow | null = null;
	let bestPercent = -1;
	let bestRank = -1;
	for (const window of candidates) {
		const usedPercent = clampUsedPercent(window.usedPercent);
		const rank = windowRank(window.name);
		if (usedPercent > bestPercent || (usedPercent === bestPercent && rank > bestRank)) {
			best = window;
			bestPercent = usedPercent;
			bestRank = rank;
		}
	}
	return best;
}

