	days: readonly DaySpend[],
	balanceCents: number | null | undefined,
	now: number,
): PrepaidMonth {
	const at = new Date(now);
	const firstDay = `${at.getFullYear()}-${String(at.getMonth() + 1).padStart(2, "0")}-01`;
	const spent = days.reduce((sum, day) => (day.day >= firstDay ? sum + Math.max(0, day.cents) : sum), 0);
	const credit = spent + Math.max(0, balanceCents ?? 0);
	return {
		spentCents: spent,
		usedPercent: credit <= 0 ? 0 : Math.min(100, (spent / credit) * 100),
		resetMs: monthEndAt(now),
	};
}

/**
 * The windows a card draws. Prepaid credit has no vendor window, so it reads as
 * a monthly credit — this month's share of what the month started with, ending
 * on the calendar's month end — exactly as a plan that refills monthly
 * (`Grok`). A card whose credit window is missing or unanchored keeps what the
 * probe reported.
 */
export function cardWindows(provider: Provider, days: readonly DaySpend[], now: number): UsageWindow[] {
	if (!provider.prepaid || provider.windows.length === 0) return provider.windows;
	const month = prepaidMonth(days, provider.balanceCents, now);
	return [
		{
			name: "monthly",
			usedPercent: month.usedPercent,
			resetAt: Math.round(month.resetMs / 1000),
		},
	];
}

export function footerSummaries(
	providers: readonly Provider[],
	now: number,
	spend?: ProviderSpend | undefined,
): FooterSummary[] {
	const rows: FooterSummary[] = [];
	for (const provider of providers) {
		const window = bottleneckWindow(cardWindows(provider, spend?.[provider.id]?.days ?? [], now));
		if (!window) continue;
		const usedPercent = clampUsedPercent(window.usedPercent);
		const resetMs = resetAtMs(window.resetAt);
		rows.push({
			id: provider.id,
			name: provider.name,
			label: formatFooterChip(window, now),
			usedPercent,
			resetMs,
		});
	}
	return rows;
}

