import { clampUsedPercent, resetAtMs } from "./format.ts";
import type { UsageWindow } from "./types.ts";

const DAY_MS = 86_400_000;
const HOUR_MS = 3_600_000;
/** Pace is judged only for long windows; session/5h resets too fast to matter. */
const WINDOW_MS: Record<string, number> = {
	weekly: 7 * DAY_MS,
	monthly: 30 * DAY_MS,
};
/** Skip the verdict while the window is too young to extrapolate. */
const MIN_ELAPSED_RATIO = 0.1;

/** Cycle length in ms for a pace-tracked window, else undefined. */
export function windowLengthMs(name: string): number | undefined {
	return WINDOW_MS[name];
}

export type Pace = { runsOutAt: number; resetAt: number };

/** Projected exhaustion before reset at the current rate, else null. */
export function windowPace(window: UsageWindow, now: number): Pace | null {
	const length = WINDOW_MS[window.name];
	const resetAt = resetAtMs(window.resetAt);
	if (!length || resetAt == null) return null;
	const used = clampUsedPercent(window.usedPercent);
	if (used <= 0 || used >= 100) return null;
	const elapsed = now - (resetAt - length);
	if (elapsed < length * MIN_ELAPSED_RATIO || elapsed >= length) return null;
	const runsOutAt = now + ((100 - used) * elapsed) / used;
	return runsOutAt < resetAt ? { runsOutAt, resetAt } : null;
}

/** First weekly/monthly window that runs out before it resets. */
export function worstPace(windows: readonly UsageWindow[], now: number): { window: UsageWindow; pace: Pace } | null {
	let best: { window: UsageWindow; pace: Pace } | null = null;
	for (const window of windows) {
		const pace = windowPace(window, now);
		if (pace && (!best || pace.runsOutAt < best.pace.runsOutAt)) {
			best = { window, pace };
		}
	}
	return best;
}

export type Budget = { perDay: number; left: number; daysLeft: number };

/**
 * Used% still available per remaining day (rounded down) so the window lasts until reset.
 * Inside the last day the cap is today's total: what today already used plus everything left.
 * A window with nothing left has no budget to spread: null, so the chart draws no line.
 */
export function dailyBudget(window: UsageWindow, now: number, usedToday = 0): Budget | null {
	const resetAt = resetAtMs(window.resetAt);
	if (resetAt == null || resetAt <= now) return null;
	const left = Math.max(0, 100 - clampUsedPercent(window.usedPercent));
	if (left <= 0) return null;
	const daysLeft = (resetAt - now) / DAY_MS;
	const perDay = daysLeft < 1 ? usedToday + left : Math.floor(left / daysLeft);
	if (perDay <= 0) return null;
	return { perDay, left, daysLeft };
}

/** Short label for the daily budget line: "max 12%/day". */
export function budgetLabel(budget: Budget): string {
	return `max ${budget.perDay}%/day`;
}

export function weekday(ms: number): string {
	return new Date(ms).toLocaleDateString("en-US", { weekday: "short" });
}

